raw:
{
  "spells": [
    {
      "id": "spell_earth_07",
      "theory": "石弹术把魔力当作短促的推进力，作用在脚边一块已有小石上。石头被加速后沿瞄准方向飞出，命中什么由瞄准决定，术者无法在飞行中改变路线。重量与形状影响飞行稳度，圆钝石比尖锐石更易偏斜。超过十米射程外，魔力对石块的牵引会迅速减弱，石头落地后不再受控。此术不创造石料，也不让石头变大或爆炸。",
      "casting": "俯身用拇指与食指捏起一块小石，另一手食指指向目标。送魔力时短促吐气，手腕向目标方向轻抖，随即松指。",
      "failure": "魔力送得过猛时，小石可能在指间碎裂，碎屑划伤手掌。方向偏斜则石头飞向侧方，可能击中附近的人或器物。若石头没被加速，它只滚落原地，但魔力已消耗。",
      "counters": [
        "举起木盾或厚布遮挡，可让石弹偏转或减速。",
        "在石弹路径上张开硬质斗篷，能兜住小石并卸去冲力。"
      ],
      "socialConsequences": "河谷乡约允许在无人处练习，但若石弹飞向牲畜或行人，会被要求赔偿。城市公会要求持许可在指定空地施放，以免伤及集市人群。港口装卸工担心石弹打中缆绳或货箱，常要求施术者远离栈桥。卖石料的人不介意，但船主会记录任何货损纠纷。",
      "law": {
        "river": "public",
        "city": "permit",
        "port": "permit"
      },
      "proficiencyEffects": [
        "0–99：石弹常偏斜，十米内命中率低，需多次练习。",
        "100–299：能稳定击中近处大目标，碎石概率下降。",
        "300–599：可控制出手力度，减少不必要的碎裂。",
        "600以上：十米内方向精确，仍无法改变飞行路线。"
      ]
    },
    {
      "id": "spell_earth_08",
      "theory": "整地术将魔力铺成一层缓慢振动的薄网，压在有限表土上。土粒在振动中重新排列，填平浅坑与隆起，但不会挖深或移走大量泥土。地下根系、石块和管道会被薄网绕过，因此不会消失或断裂。平整效果持续约一分钟，之后表土会因踩踏和雨水逐渐恢复自然状态。此术不改变土壤肥力，也不压实深层地基。",
      "casting": "双掌张开，掌心朝下，从地块一端缓慢走向另一端。每步停顿时，脚掌轻顿，让魔力沿地面铺开。",
      "failure": "魔力网铺得不均时，地面会出现波浪状起伏，比原来更难走。若中途停步，已铺开的区域会局部下沉，形成浅坑。过度用力可能让表土松散，踩上去扬起灰尘。",
      "counters": [
        "在田地上覆盖草席或木板，可阻止魔力直接接触表土。",
        "向地面泼水使泥土黏结，能减弱振动铺网的效果。"
      ],
      "socialConsequences": "河谷农户常在播种前请人整平小块菜地，乡约见证下不收费。城市园丁和公会苗圃欢迎此术，但要求避开地下水管与煤气管，损坏须赔偿。港口货场用平整地面堆放轻货，但搬运工担心表土被压松后陷车。石匠和夯土匠认为此术不能替代真正的地基工程。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "0–99：平整后仍有小起伏，需人工踩踏补平。",
        "100–299：能均匀铺网，浅坑填平效果明显改善。",
        "300–599：可控制振动幅度，避免表土过度松散。",
        "600以上：有限表土平整如初，仍不触及深根管道。"
      ]
    },
    {
      "id": "spell_earth_09",
      "theory": "矿纹显露将魔力渗入近处岩土，使含矿条带与周围土石产生轻微色差。含铁处偏暗红，含铜处偏青绿，含铅处偏灰白，但颜色很淡，需要斜看才能分辨。此术只显示矿物分布，不显示深度、品位或储量，也不把矿石从岩层中分离出来。产量仍须靠开采与冶炼决定，条带可能薄到不值得挖掘。持续约一分半后，色差会自行消退。",
      "casting": "取一小块树脂在掌心搓热，单膝跪地，将树脂按在岩面上，闭眼默数三次呼吸。睁眼后沿岩面缓慢扫视。",
      "failure": "树脂搓得不够热时，色差极淡，几乎看不出条带。魔力渗得过深会让整片岩面泛出杂色，反而掩盖真正矿纹。若岩面太湿，树脂滑落，术式中断，魔力白费。",
      "counters": [
        "用湿泥或苔藓覆盖岩面，可阻挡魔力渗入。",
        "在岩面上撒铁砂，能干扰色差，使矿纹难以辨认。"
      ],
      "socialConsequences": "河谷探矿者愿意用此术初查露头岩，但乡约要求不得在他人田界内擅自施放。城市矿业公会要求持许可在公共岩壁使用，私自勘探可能被视为窃取矿权线索。港口检货员用它抽查压舱石是否含矿，但船主担心色差引起误会，坚持先问明货主。冶炼坊主认为此术只省脚力，不省炉火。",
      "law": {
        "river": "public",
        "city": "public",
        "port": "public"
      },
      "proficiencyEffects": [
        "0–99：色差极淡，常需斜看并反复确认。",
        "100–299：能分辨常见铁矿与铜矿条带的大致走向。",
        "300–599：可减少杂色干扰，条带边界更清楚。",
        "600以上：二十米内矿纹显露稳定，仍不显示深度品位。"
      ]
    }
  ]
}
